        for c in range(cols):
            if test[r][c] != 9 and test[r][c] != 4:
                sources.append((r, c, test[r][c]))

    result = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if test[r][c] == 4:
                result[r][c] = 4
            else:
                # Find nearest source by Manhattan distance
                min_dist = float('inf')
                nearest_val = test[r][c]  # default to current

                for sr, sc, sval in sources:
                    dist = abs(r - sr) + abs(c - sc)
                    if dist < min_dist:
                        min_dist = dist
                        nearest_val = sval
